const fs = require("fs");
const path = require("path");

const SOURCE_PATH = path.join(__dirname, "..", "..", "instances-source.json");
const OUTPUT_PATH = path.join(__dirname, "..", "..", "instances.json");
const README_PATH = path.join(__dirname, "..", "..", "README.md");
const INSTANCES_MD_PATH = path.join(__dirname, "..", "..", "INSTANCES.md");

const START_MARKER = "<!-- INSTANCES:START -->";
const END_MARKER = "<!-- INSTANCES:END -->";

function buildTable(instances) {
  const header =
    "| URL | Region | Proxy | Cloudflare | Version | Versions Behind | Custom Source | Custom Privacy Policy |\n" +
    "|-----|--------|-------|------------|---------|------------------|----------------|------------------------|";

  const rows = instances.map((i) => {
    const status = i.reachable ? "" : " ⚠️ unreachable";
    const url = `[${i.url}](${i.url})${status}`;
    const proxy = i.proxy ? "✅" : "❌";
    const cloudflare = i.cloudflare ? "✅" : "❌";
    const behind = i.versions_behind === null ? "–" : i.versions_behind;
    const customSource = i.custom_source
      ? i.source_url
        ? `[yes](${i.source_url})`
        : "yes"
      : "no";
    const privacyPolicy = i.custom_privacy_policy
      ? i.privacy_policy_url
        ? `[yes](${i.privacy_policy_url})`
        : "yes"
      : "no";

    return `| ${url} | ${i.region} | ${proxy} | ${cloudflare} | ${i.version} | ${behind} | ${customSource} | ${privacyPolicy} |`;
  });

  return [header, ...rows].join("\n");
}

function upsertSection(filePath, table, fallbackContent) {
  const table_with_markers = `${START_MARKER}\n${table}\n${END_MARKER}`;

  let content;
  if (fs.existsSync(filePath)) {
    content = fs.readFileSync(filePath, "utf-8");
  } else {
    content = fallbackContent;
  }

  if (content.includes(START_MARKER) && content.includes(END_MARKER)) {
    const before = content.split(START_MARKER)[0];
    const after = content.split(END_MARKER)[1];
    content = `${before}${table_with_markers}${after}`;
  } else {
    content = `${content.trim()}\n\n${table_with_markers}\n`;
  }

  fs.writeFileSync(filePath, content);
}

async function fetchApiInfo(baseUrl) {
  const apiUrl = `${baseUrl.replace(/\/$/, "")}/api/v1`;
  try {
    const res = await fetch(apiUrl, { signal: AbortSignal.timeout(10000) });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const UPSTREAM_WEBSITE = "https://github.com/TeamVivid/Vivid";

    const hasPrivacyPolicy =
      typeof data.privacyPolicyUrl === "string" && data.privacyPolicyUrl.trim() !== "";

    return {
      ok: true,
      version: data.version ?? "unknown",
      versions_behind: typeof data.behind === "number" ? data.behind : null,
      custom_source: typeof data.website === "string" && data.website.trim() !== UPSTREAM_WEBSITE,
      source_url: data.website && data.website.trim() !== "" ? data.website : null,
      custom_privacy_policy: hasPrivacyPolicy,
      privacy_policy_url: hasPrivacyPolicy ? data.privacyPolicyUrl : null,
    };
  } catch (err) {
    return {
      ok: false,
      version: "unreachable",
      versions_behind: null,
      custom_source: null,
      source_url: null,
      custom_privacy_policy: null,
      privacy_policy_url: null,
      error: String(err.message || err),
    };
  }
}

async function main() {
  const source = JSON.parse(fs.readFileSync(SOURCE_PATH, "utf-8"));

  const instances = [];
  for (const entry of source.instances) {
    const info = await fetchApiInfo(entry.url);
    instances.push({
      url: entry.url,
      region: entry.region,
      proxy: entry.proxy,
      cloudflare: entry.cloudflare,
      reachable: info.ok,
      version: info.version,
      versions_behind: info.versions_behind,
      custom_source: info.custom_source,
      source_url: info.source_url,
      custom_privacy_policy: info.custom_privacy_policy,
      privacy_policy_url: info.privacy_policy_url,
      ...(info.error ? { error: info.error } : {}),
    });
  }

  const output = {
    generated_at: new Date().toISOString(),
    instances,
  };

  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(output, null, 2) + "\n");
  console.log(`Wrote ${instances.length} instances to ${OUTPUT_PATH}`);

  const table = buildTable(instances);

  upsertSection(
    README_PATH,
    table,
    "# Instances\n"
  );
  console.log(`Updated ${README_PATH}`);

  upsertSection(
    INSTANCES_MD_PATH,
    table,
    "# Instances\n\nAuto-generated list of all known instances. Do not edit this file manually; it is overwritten by GitHub Actions.\n"
  );
  console.log(`Updated ${INSTANCES_MD_PATH}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
